   updatePageTitle() {
     const segs = this.router.url.split('?')[0].split('/').filter(Boolean);
     const path = segs[1] || 'dashboard';
     const sub = segs[2];
     const titles: Record<string, string> = {
       dashboard: 'Dashboard',
       pacientes: 'Pacientes',
       evolucoes: 'Evoluções',
       responsaveis: 'Responsáveis',
       escolas: 'Escolas',
