export function getInstrument(code: string): ScreeningInstrumentDef | undefined {
  return SCREENING_INSTRUMENTS.find((i) => i.code === code);
}

function num(v: any): number {
  const n = typeof v === 'number' ? v : parseInt(String(v), 10);
  return Number.isFinite(n) ? n : 0;
}

function buildDimensions(
  def: ScreeningInstrumentDef,
  scores: Record<string, number>,
  maxPerItem: number,
) {
  const dims: Record<string, { label: string; score: number; max: number; percentage: number }> = {};
  if (!def.dimensions) return dims;
  for (const d of def.dimensions) {
    const items = def.items.filter((it) => it.dimension === d.id);
    let score = 0;
    for (const it of items) score += scores[it.id] ?? 0;
    const max = items.length * maxPerItem;
    dims[d.id] = {
      label: d.label,
      score,
      max,
      percentage: max > 0 ? Math.round((score / max) * 100) : 0,
    };
  }
  return dims;
}

function scoreMCHAT(answers: Record<string, any>): ScreeningResult {
  const def = getInstrument('MCHAT_R')!;
  let fails = 0;
  let criticalFails = 0;
  for (const it of def.items) {
    const ans = answers[it.id];
    if (ans === undefined || ans === null || ans === '') continue;
    const failed = it.reverse ? ans === 'sim' : ans === 'nao';
    if (failed) {
      fails += 1;
      if (it.critical) criticalFails += 1;
    }
  }
  const answered = def.items.filter((it) => answers[it.id] !== undefined && answers[it.id] !== null && answers[it.id] !== '').length;
  let riskLevel: string;
  let summary: string;
  if (fails >= 8) {
    riskLevel = 'ALTO';
    summary = `Risco ALTO para TEA: ${fails} de ${answered} itens com falha (${criticalFails} críticos). Recomenda-se encaminhamento imediato para avaliação diagnóstica especializada.`;
  } else if (fails >= 3) {
    riskLevel = 'MODERADO';
    summary = `Risco MODERADO: ${fails} itens com falha (${criticalFails} críticos). Recomenda-se aplicar a Entrevista de Seguimento (M-CHAT-R/F) para confirmar os itens de falha.`;
  } else {
    riskLevel = 'BAIXO';
    summary = `Risco BAIXO para TEA: ${fails} itens com falha (${criticalFails} críticos). Manter monitoramento do desenvolvimento infantil.`;
  }
  return {
    scores: { total: fails, max: 20, answered, criticalFails },
    riskLevel,
    summary,
  };
}

function scoreSNAP(answers: Record<string, any>, respondent?: string): ScreeningResult {
  const def = getInstrument('SNAP_IV')!;
  const dimScores: Record<string, { score: number; count: number; mean: number }> = {};
  for (const d of def.dimensions!) {
    const items = def.items.filter((it) => it.dimension === d.id);
    let score = 0;
    let count = 0;
    for (const it of items) {
      const v = num(answers[it.id]);
      score += v;
      if (v >= 2) count += 1;
    }
    dimScores[d.id] = { score, count, mean: Math.round((score / items.length) * 100) / 100 };
  }
  const inat = dimScores['desatencao'];
  const hiper = dimScores['hiperatividade'];
  const maxSymptoms = Math.max(inat.count, hiper.count);
  let riskLevel: string;
  let summary: string;
  if (maxSymptoms >= 6) {
    riskLevel = 'ELEVADO';
    const subtype =
      inat.count >= 6 && hiper.count >= 6
        ? 'combinado (desatenção + hiperatividade/impulsividade)'
        : inat.count >= 6
          ? 'predominantemente desatento'
          : 'predominantemente hiperativo/impulsivo';
    summary = `Rastreio SUGESTIVO de TDAH (subtipo ${subtype}): ${inat.count} sintomas de desatenção e ${hiper.count} de hiperatividade/impulsividade. Recomenda-se avaliação diagnóstica especializada (informante: ${respondent || 'não informado'}).`;
  } else if (maxSymptoms >= 3) {
    riskLevel = 'MODERADO';
    summary = `Indicadores parciais de TDAH: ${inat.count} sintomas de desatenção e ${hiper.count} de hiperatividade/impulsividade. Monitorar e considerar avaliação complementar.`;
  } else {
    riskLevel = 'BAIXO';
    summary = `Rastreio sem indicadores significativos de TDAH: ${inat.count} sintomas de desatenção e ${hiper.count} de hiperatividade/impulsividade (informante: ${respondent || 'não informado'}).`;
  }
  return {
    scores: {
      total: inat.score + hiper.score,
      max: 54,
      dimensions: {
        desatencao: { label: 'Desatenção', score: inat.score, max: 27, mean: inat.mean, symptoms: inat.count },
        hiperatividade: { label: 'Hiperatividade/Impulsividade', score: hiper.score, max: 27, mean: hiper.mean, symptoms: hiper.count },
      },
    },
    riskLevel,
    summary,
  };
}

function scoreATA(answers: Record<string, any>): ScreeningResult {
  const def = getInstrument('ATA')!;
  let total = 0;
  let answered = 0;
  for (const it of def.items) {
    const v = num(answers[it.id]);
    total += v;
    if (answers[it.id] !== undefined && answers[it.id] !== null && answers[it.id] !== '') answered += 1;
  }
  let riskLevel: string;
  let summary: string;
  if (total >= 15) {
    riskLevel = 'ELEVADO';
    summary = `Pontuação ATA ${total}/46 — risco ELEVADO de traços autísticos (ponto de corte: 15). Recomenda-se encaminhamento para avaliação diagnóstica especializada.`;
  } else if (total >= 8) {
    riskLevel = 'MODERADO';
    summary = `Pontuação ATA ${total}/46 — indicadores moderados de traços autísticos. Manter acompanhamento e considerar avaliação complementar.`;
  } else {
    riskLevel = 'BAIXO';
    summary = `Pontuação ATA ${total}/46 — sem indicadores significativos de traços autísticos.`;
  }
  return { scores: { total, max: 46, answered }, riskLevel, summary };
}

function scoreASRS(answers: Record<string, any>): ScreeningResult {
  const def = getInstrument('ASRS_18')!;
  let partA = 0;
  let partB = 0;
  for (const it of def.items) {
    const v = num(answers[it.id]);
    if (it.dimension === 'parteA') partA += v;
    else partB += v;
  }
  let riskLevel: string;
  let summary: string;
  if (partA >= 14 || partB >= 15) {
    riskLevel = 'ELEVADO';
    summary = `Rastreio SUGESTIVO de TDAH no adulto: Parte A ${partA}/24 (corte: 14) e Parte B ${partB}/48 (corte: 15). Recomenda-se avaliação diagnóstica com profissional habilitado.`;
  } else if (partA >= 9 || partB >= 10) {
    riskLevel = 'MODERADO';
    summary = `Indicadores parciais de TDAH no adulto: Parte A ${partA}/24 e Parte B ${partB}/48. Monitorar sintomas e considerar avaliação complementar.`;
  } else {
    riskLevel = 'BAIXO';
    summary = `Rastreio sem indicadores significativos de TDAH no adulto: Parte A ${partA}/24 e Parte B ${partB}/48.`;
  }
  return {
    scores: {
      total: partA + partB,
      max: 72,
      dimensions: {
        parteA: { label: 'Parte A — Triagem', score: partA, max: 24, percentage: Math.round((partA / 24) * 100) },
        parteB: { label: 'Parte B — Sintomas', score: partB, max: 48, percentage: Math.round((partB / 48) * 100) },
      },
    },
    riskLevel,
    summary,
  };
}

function scoreHabilidadesSociais(answers: Record<string, any>): ScreeningResult {
  const def = getInstrument('HABILIDADES_SOCIAIS')!;
  const dims = buildDimensions(def, answers, 4);
  let total = 0;
  let max = 0;
  for (const d of def.dimensions!) {
    total += dims[d.id].score;
    max += dims[d.id].max;
  }
  const overall = max > 0 ? Math.round((total / max) * 100) : 0;
  const weakest = [...def.dimensions!].sort((a, b) => dims[a.id].percentage - dims[b.id].percentage)[0];
  let riskLevel: string;
  let summary: string;
  if (overall >= 75) {
    riskLevel = 'BAIXO';
    summary = `Repertório de habilidades sociais adequado (${overall}%). Dimensão com menor índice: ${dims[weakest.id].label} (${dims[weakest.id].percentage}%).`;
  } else if (overall >= 50) {
    riskLevel = 'MODERADO';
    summary = `Repertório de habilidades sociais em desenvolvimento (${overall}%). Dimensão com menor índice: ${dims[weakest.id].label} (${dims[weakest.id].percentage}%) — recomenda-se estimulação direcionada.`;
  } else {
    riskLevel = 'ELEVADO';
    summary = `Repertório de habilidades sociais SIGNIFICATIVAMENTE reduzido (${overall}%). Dimensão crítica: ${dims[weakest.id].label} (${dims[weakest.id].percentage}%) — recomenda-se intervenção estruturada.`;
  }
  return { scores: { total, max, overall, dimensions: dims }, riskLevel, summary };
}

const SCORERS: Record<string, (answers: Record<string, any>, respondent?: string) => ScreeningResult> = {
  MCHAT_R: scoreMCHAT,
  SNAP_IV: scoreSNAP,
  ATA: scoreATA,
  ASRS_18: scoreASRS,
  HABILIDADES_SOCIAIS: scoreHabilidadesSociais,
};

export function scoreScreening(code: string, answers: Record<string, any>, respondent?: string): ScreeningResult {
  const scorer = SCORERS[code];
  if (!scorer) {
    throw new Error(`Instrumento de rastreio desconhecido: ${code}`);
  }
  return scorer(answers, respondent);
}

import { Router } from 'express';
import prisma from '../lib/prisma';
import { scoped } from '../lib/tenant';
import { authenticate } from '../middleware';
import { SCREENING_INSTRUMENTS, getInstrument, scoreScreening } from '../lib/screening-instruments';

const router = Router();
router.use(authenticate);

router.get('/instruments', (_req, res) => {
  res.json({
    data: SCREENING_INSTRUMENTS.map((i) => ({
      code: i.code,
      name: i.name,
      description: i.description,
      target: i.target,
      optionType: i.optionType,
      options: i.options,
      dimensions: i.dimensions,
      itemsCount: i.items.length,
    })),
  });
});

router.get('/instruments/:code', (req, res) => {
  const def = getInstrument(req.params.code);
  if (!def) return res.status(404).json({ error: 'Instrumento não encontrado' });
  res.json(def);
});

router.get('/', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { pacienteId, instrument } = req.query;
  const where: any = {};
  if (pacienteId) where.pacienteId = pacienteId;
  if (instrument) where.instrument = instrument;
  const data = await db.screeningAssessment.findMany({
    where,
    include: { paciente: true, profissional: { select: { id: true, name: true } } },
    orderBy: { assessedAt: 'desc' },
  });
  res.json({ data, total: data.length });
});

router.get('/:id', async (req, res) => {
  if (req.params.id === 'instruments') return;
  const db = scoped(prisma, req.user?.tenantId);
  const found = await db.screeningAssessment.findUnique({
    where: { id: req.params.id },
    include: { paciente: true, profissional: { select: { id: true, name: true } } },
  });
  if (!found) return res.status(404).json({ error: 'Rastreio não encontrado' });
  res.json(found);
});

function buildPayload(body: any, profissionalId: string) {
  const instrument = getInstrument(body.instrument);
  if (!instrument) {
    const err: any = new Error('Instrumento de rastreio inválido');
    err.status = 400;
    throw err;
  }
  const answers = body.answers || {};
  const result = scoreScreening(body.instrument, answers, body.respondent);
  return {
    pacienteId: body.pacienteId,
    profissionalId,
    instrument: body.instrument,
    respondent: body.respondent || null,
    answers: JSON.stringify(answers),
    scores: JSON.stringify(result.scores),
    riskLevel: result.riskLevel,
    summary: result.summary,
    notes: body.notes || null,
    assessedAt: body.assessedAt ? new Date(body.assessedAt) : new Date(),
  };
}

router.post('/', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const data = buildPayload(req.body, req.user!.id);
  const created = await db.screeningAssessment.create({ data });
  res.status(201).json(created);
});

router.put('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const data = buildPayload(req.body, req.user!.id);
  const updated = await db.screeningAssessment.update({ where: { id: req.params.id }, data });
  res.json(updated);
});

router.delete('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  await db.screeningAssessment.delete({ where: { id: req.params.id } });
  res.status(204).send();
});

export default router;

import { Router } from 'express';
import prisma from '../lib/prisma';
import { scoped } from '../lib/tenant';
import { authenticate } from '../middleware';
import { getInstrument } from '../lib/screening-instruments';

const router = Router();
router.use(authenticate);

function fmtDate(d: any): string {
  if (!d) return '';
  const date = d instanceof Date ? d : new Date(d);
  if (Number.isNaN(date.getTime())) return String(d);
  return date.toLocaleDateString('pt-BR');
}

function clean(s?: string | null): string {
  return (s || '').trim();
}

router.post('/generate-draft', async (req, res) => {
  const { pacienteId, tipo } = req.body;
  if (!pacienteId) return res.status(400).json({ error: 'pacienteId é obrigatório' });
  const db = scoped(prisma, req.user?.tenantId);

  const [paciente, anamnese, evolucoes, protocolo, aba, rastreios, encaminhamentos, sessoes] =
    await Promise.all([
      db.paciente.findUnique({
        where: { id: pacienteId },
        include: { responsible: true, school: true },
      }),
      db.anamnese.findFirst({ where: { pacienteId }, orderBy: { createdAt: 'desc' } }),
      db.sessionRecord.findMany({ where: { pacienteId }, orderBy: { date: 'desc' }, take: 6 }),
      db.protocolEvaluation.findFirst({ where: { pacienteId }, orderBy: { date: 'desc' } }),
      db.aBAAssessment.findMany({ where: { patientId: pacienteId }, orderBy: { assessedAt: 'desc' }, take: 4 }),
      db.screeningAssessment.findMany({ where: { pacienteId }, orderBy: { assessedAt: 'desc' } }),
      db.encaminhamento.findMany({ where: { pacienteId }, orderBy: { createdAt: 'desc' }, take: 3 }),
      db.sessao.findMany({ where: { pacienteId }, orderBy: { date: 'desc' }, take: 3 }),
    ]);

  if (!paciente) return res.status(404).json({ error: 'Paciente não encontrado' });

  const lines: string[] = [];
  const hoje = new Date().toLocaleDateString('pt-BR');
  const tipoLabel = { LAUDO: 'Laudo', PARECER: 'Parecer', RELATORIO: 'Relatório' }[tipo as string] || 'Relatório';

  lines.push(`${tipoLabel} de Avaliação`);
  lines.push('');
  lines.push(`Paciente: ${paciente.name} (${paciente.age || 'idade não informada'}${paciente.birthDate ? `, nascimento: ${fmtDate(paciente.birthDate)}` : ''})`);
  lines.push(`Responsável: ${clean(paciente.responsible?.name) || 'não informado'}`);
  lines.push(`Escola: ${clean(paciente.school?.name) || 'não informada'}`);
  lines.push(`Data do documento: ${hoje}`);
  lines.push('');

  lines.push('1. Queixa e histórico');
  const an = anamnese;
  lines.push(
    clean(an?.queixaPrincipal)
      ? `Queixa principal: ${an.queixaPrincipal}`
      : 'Queixa principal: (não registrada na anamnese).',
  );
  if (clean(an?.historiaQueixa)) lines.push(`História da queixa: ${an.historiaQueixa}`);
  if (clean(an?.historicoEscolar)) lines.push(`Histórico escolar: ${an.historicoEscolar}`);
  if (clean(an?.dificuldadesAprendizado)) lines.push(`Dificuldades de aprendizagem: ${an.dificuldadesAprendizado}`);
  if (clean(an?.interacaoSocial)) lines.push(`Interação social: ${an.interacaoSocial}`);
  if (clean(an?.desenvolvimentoLinguagem)) lines.push(`Desenvolvimento da linguagem: ${an.desenvolvimentoLinguagem}`);
  if (clean(an?.diagnostico)) lines.push(`Diagnóstico prévio informado: ${an.diagnostico}`);
  lines.push('');

  lines.push('2. Instrumentos e avaliações aplicados');
  if (rastreios.length > 0) {
    lines.push('Rastreios/triagens:');
    for (const r of rastreios) {
      const def = getInstrument(r.instrument);
      const scores = JSON.parse(r.scores || '{}');
      lines.push(
        `- ${def?.name || r.instrument} (${fmtDate(r.assessedAt)}): ${scores?.total ?? '-'} pontos — risco ${r.riskLevel}. ${r.summary || ''}`,
      );
    }
  } else {
    lines.push('Rastreios/triagens: nenhum registro encontrado.');
  }
  if (protocolo) {
    lines.push(
      `- Protocolo TEA (${fmtDate(protocolo.date)}): ${protocolo.totalEvaluations} itens avaliados, média ${protocolo.averageScore} (máx. ${protocolo.maxScore}).`,
    );
  }
  if (aba.length > 0) {
    for (const a of aba) {
      lines.push(`- Avaliação ABA ${a.protocolType} (${fmtDate(a.assessedAt)}): pontuação ${a.totalScore ?? '-'}.`);
    }
  }
  if (sessoes.length > 0) {
    lines.push('Sessões registradas:');
    for (const s of sessoes) lines.push(`- ${fmtDate(s.date)}: ${clean(s.objetivo) || clean(s.summary) || 'sem registro de objetivo'}`);
  }
  lines.push('');

  lines.push('3. Evolução observada');
  if (evolucoes.length > 0) {
    for (const e of evolucoes) {
      const metrics = [e.focus, e.engagement, e.skillProgress, e.behavior].filter((v) => typeof v === 'number');
      const media = metrics.length > 0 ? (metrics.reduce((a, b) => a + (b as number), 0) / metrics.length).toFixed(1) : '—';
      const texto = clean(e.summary) || clean(e.activities) || 'sem registro';
      lines.push(`- ${fmtDate(e.date)} (métricas ${media}/5): ${texto}`);
    }
  } else {
    lines.push('Ainda não há registros de evolução para este paciente.');
  }
  lines.push('');

  if (encaminhamentos.length > 0) {
    lines.push('4. Encaminhamentos');
    for (const en of encaminhamentos) {
      lines.push(`- ${clean(en.motivo) || 'sem motivo registrado'} (${en.status || 'sem status'})`);
    }
    lines.push('');
  }

  lines.push('5. Síntese clínica');
  const sinteses: string[] = [];
  if (rastreios.some((r) => ['ELEVADO', 'ALTO'].includes(r.riskLevel))) {
    sinteses.push('os rastreios aplicados indicam sinais que merecem atenção e encaminhamento para avaliação diagnóstica complementar');
  }
  if (protocolo) {
    const pct = protocolo.maxScore > 0 ? Math.round((protocolo.averageScore / protocolo.maxScore) * 100) : null;
    if (pct !== null && pct < 40) sinteses.push('o desempenho no protocolo TEA encontra-se abaixo do esperado para a faixa etária');
    else if (pct !== null && pct >= 70) sinteses.push('o desempenho no protocolo TEA indica boa evolução nas habilidades avaliadas');
  }
  if (evolucoes.length > 0) {
    const medias = evolucoes.map((e) => {
      const m = [e.focus, e.engagement, e.skillProgress, e.behavior].filter((v) => typeof v === 'number');
      return m.length ? m.reduce((a, b) => a + (b as number), 0) / m.length : 0;
    });
    const primeira = medias[medias.length - 1];
    const ultima = medias[0];
    if (primeira > 0 && ultima > primeira) sinteses.push('observa-se evolução positiva nas métricas das sessões ao longo do período');
    else if (primeira > 0 && ultima < primeira) sinteses.push('as métricas das sessões indicam oscilação/regressão que merece revisão do plano terapêutico');
  }
  lines.push(
    sinteses.length > 0
      ? `A partir dos dados disponíveis, ${sinteses.join('; ')}.`
      : 'A partir dos dados disponíveis no prontuário, ainda não é possível estabelecer síntese conclusiva; recomenda-se completar as avaliações.',
  );
  lines.push('');

  lines.push('6. Conduta e encaminhamentos');
  lines.push('Recomenda-se: (a preencher)');
  lines.push('');

  lines.push('____________________________');
  lines.push('Profissional responsável');
  lines.push('');
  lines.push('*Documento gerado como rascunho com base nos registros clínicos. O conteúdo deve ser revisado, complementado e assinado pelo profissional responsável antes de qualquer uso.*');

  const content = lines.join('\n');
  const title = `${tipoLabel} — ${paciente.name} (${hoje})`;

  res.json({ title, content });
});

export default router;

import { Router } from 'express';
import prisma from '../lib/prisma';
import { scoped } from '../lib/tenant';
import { authenticate } from '../middleware';
import { getInstrument } from '../lib/screening-instruments';

const router = Router();
router.use(authenticate);

router.get('/:pacienteId', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { pacienteId } = req.params;

  const [evolucoes, rastreios, protocolo, aba, sessoes, financeiro, encaminhamentos] = await Promise.all([
    db.sessionRecord.findMany({ where: { pacienteId }, orderBy: { date: 'desc' } }),
    db.screeningAssessment.findMany({ where: { pacienteId }, orderBy: { assessedAt: 'desc' } }),
    db.protocolEvaluation.findFirst({ where: { pacienteId }, orderBy: { date: 'desc' } }),
    db.aBAAssessment.findMany({ where: { patientId: pacienteId }, orderBy: { assessedAt: 'desc' } }),
    db.sessao.findMany({ where: { pacienteId }, orderBy: { date: 'desc' } }),
    db.financeiroSessao.findMany({ where: { pacienteId, status: 'PENDENTE' } }),
    db.encaminhamento.findMany({ where: { pacienteId, status: 'PENDENTE' } }),
  ]);

  const insights: { icon: string; color: string; text: string }[] = [];
  const alertas: { icon: string; color: string; text: string }[] = [];

  if (rastreios.length > 0) {
    const ultimo = rastreios[0];
    const def = getInstrument(ultimo.instrument);
    const scores = JSON.parse(ultimo.scores || '{}');
    if (ultimo.riskLevel === 'ELEVADO' || ultimo.riskLevel === 'ALTO') {
      alertas.push({
        icon: 'warning',
        color: 'red',
        text: `Último rastreio (${def?.name || ultimo.instrument}, ${new Date(ultimo.assessedAt).toLocaleDateString('pt-BR')}) apontou risco ${ultimo.riskLevel} — ${ultimo.summary || ''}`,
      });
    } else {
      insights.push({
        icon: 'fact_check',
        color: 'emerald',
        text: `Último rastreio (${def?.name || ultimo.instrument}): risco ${ultimo.riskLevel} (${scores?.total ?? '-'} pontos).`,
      });
    }
  }

  if (aba.length > 0) {
    const latest = aba[0];
    const previous = aba.find((a) => a.id !== latest.id && a.protocolType === latest.protocolType);
    if (previous && typeof latest.totalScore === 'number' && typeof previous.totalScore === 'number') {
      const delta = Math.round((latest.totalScore - previous.totalScore) * 10) / 10;
      if (delta > 0) {
        insights.push({
          icon: 'trending_up',
          color: 'emerald',
          text: `ABA ${latest.protocolType}: evolução de ${previous.totalScore} → ${latest.totalScore} pontos (+${delta}) entre avaliações.`,
        });
      } else {
        alertas.push({
          icon: 'trending_down',
          color: 'red',
          text: `ABA ${latest.protocolType}: pontuação recuou de ${previous.totalScore} → ${latest.totalScore} (${delta}) na última reavaliação.`,
        });
      }
    } else {
      insights.push({
        icon: 'psychology',
        color: 'sky',
        text: `${aba.length} avaliação(ões) ABA registrada(s); última: ${latest.protocolType} (${latest.totalScore ?? '-'} pontos).`,
      });
    }
  }

  if (protocolo) {
    const pct = protocolo.maxScore > 0 ? Math.round((protocolo.averageScore / protocolo.maxScore) * 100) : null;
    if (pct !== null && pct < 40) {
      alertas.push({ icon: 'fact_check', color: 'amber', text: `Protocolo TEA (${protocolo.date}): ${pct}% de aproveitamento — abaixo do esperado.` });
    } else if (pct !== null) {
      insights.push({ icon: 'fact_check', color: 'emerald', text: `Protocolo TEA: ${pct}% de aproveitamento na última aplicação.` });
    }
  }

  if (evolucoes.length > 0) {
    const medias = evolucoes.map((e) => {
      const m = [e.focus, e.engagement, e.skillProgress, e.behavior].filter((v) => typeof v === 'number');
      return m.length ? m.reduce((a, b) => a + (b as number), 0) / m.length : 0;
    });
    const primeira = medias[medias.length - 1];
    const ultima = medias[0];
    const mediaGeral = medias.length ? medias.reduce((a, b) => a + b, 0) / medias.length : 0;
    insights.push({
      icon: 'star',
      color: 'amber',
      text: `${evolucoes.length} evolução(ões) registrada(s); média geral ${mediaGeral.toFixed(1)}/5.${primeira > 0 && ultima > primeira ? ' Tendência de melhora nas métricas.' : ''}`,
    });
    if (primeira > 0 && ultima < primeira) {
      alertas.push({ icon: 'trending_down', color: 'red', text: 'Métricas das últimas sessões estão abaixo das iniciais — revisar plano terapêutico.' });
    }
  }

  if (sessoes.length > 0) {
    insights.push({ icon: 'event', color: 'sky', text: `${sessoes.length} sessão(ões) registrada(s); última em ${new Date(sessoes[0].date).toLocaleDateString('pt-BR')}.` });
  } else {
    insights.push({ icon: 'event', color: 'slate', text: 'Nenhuma sessão registrada ainda.' });
  }

  if (encaminhamentos.length > 0) {
    alertas.push({ icon: 'forward', color: 'sky', text: `${encaminhamentos.length} encaminhamento(s) pendente(s) de resposta.` });
  }

  if (financeiro.length > 0) {
    alertas.push({ icon: 'payments', color: 'amber', text: `${financeiro.length} cobrança(s) pendente(s) de pagamento.` });
  }

  res.json({
    pacienteId,
    totalEvolucoes: evolucoes.length,
    totalRastreios: rastreios.length,
    totalSessoes: sessoes.length,
    insights,
    alertas,
  });
});

export default router;

